<script lang="ts">import type {OperationalStatus} from '$lib/server/content/types';let {title,status}:{title:string;status:OperationalStatus}=$props();const labels={unconfigured:'未配置','no-record':'尚无记录',running:'进行中',success:'最近一次成功',failure:'最近一次失败',stale:'记录陈旧','read-failure':'读取失败',unknown:'结果待确认'};const date=(d:Date|null)=>d?new Date(d).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'无记录';</script>
<section><h2>{title}</h2><p role="status">{labels[status.state]}</p><dl><dt>事件发生于</dt><dd>{date(status.eventAt)}</dd><dt>数据采集于</dt><dd>{date(status.collectedAt)}</dd><dt>最近成功</dt><dd>{date(status.lastSuccessAt)}</dd><dt>最近失败</dt><dd>{date(status.lastFailureAt)}</dd></dl>{#if status.detail}<p>{status.detail}</p>{/if}{#if status.state!=='success'}<p>请检查任务配置与运行记录；页面刷新不会产生新的完成记录。</p>{/if}</section><style>section{border:1px solid var(--line);border-radius:16px;padding:24px}dd{margin:0 0 12px}dt{color:var(--muted)}</style>
